import java.awt.*
import java.util.Properties
import javax.swing.*
data class Step(val name:String,val seconds:Int)
fun encode(steps:List<Step>):Properties{require(steps.size in 1..100);val p=Properties();p.setProperty("count",steps.size.toString());steps.forEachIndexed{i,s->require(s.name.isNotBlank()&&s.seconds in 1..3600);p.setProperty("$i.name",s.name);p.setProperty("$i.seconds",s.seconds.toString())};return p}
fun decode(p:Properties):MutableList<Step>{val n=p.getProperty("count").toInt();require(n in 1..100);val out=(0 until n).map{Step(p.getProperty("$it.name"),p.getProperty("$it.seconds").toInt())}.toMutableList();encode(out);return out}
fun active(steps:List<Step>,elapsed:Long):Pair<Int,Long>{require(elapsed>=0);var rest=elapsed;for(i in steps.indices){if(rest<steps[i].seconds)return i to (steps[i].seconds-rest);rest-=steps[i].seconds};return -1 to 0}
fun main(args:Array<String>){if(args.contains("--self-test")){val steps=listOf(Step("Work",20),Step("Rest",10));check(active(steps,19)==0 to 1L);check(active(steps,20)==1 to 10L);check(active(steps,30).first == -1);check(decode(encode(steps))==steps);println("Interval boundaries and composition round trip passed");return};SwingUtilities.invokeLater{val f=JFrame("Interval Workout Composer").apply{defaultCloseOperation=JFrame.EXIT_ON_CLOSE;setSize(850,600)};var steps=mutableListOf(Step("Work",30),Step("Rest",15));var started=0L;var running=false;val panel=JPanel(BorderLayout(12,12));panel.border=BorderFactory.createEmptyBorder(18,18,18,18);f.contentPane=panel;val list=JList<String>();val model=DefaultListModel<String>();list.model=model;panel.add(JScrollPane(list),BorderLayout.CENTER);val status=JLabel("Ready",SwingConstants.CENTER);status.font=Font("SansSerif",Font.BOLD,32);panel.add(status,BorderLayout.NORTH);val bar=JPanel();val name=JTextField("Work",10);val seconds=JSpinner(SpinnerNumberModel(30,1,3600,1));bar.add(name);bar.add(seconds);panel.add(bar,BorderLayout.SOUTH);fun draw(){model.clear();steps.forEach{model.addElement("${it.name}: ${it.seconds}s")}};fun button(label:String,action:()->Unit){val b=JButton(label);bar.add(b);b.addActionListener{try{action();draw()}catch(e:Exception){JOptionPane.showMessageDialog(f,e.message)}}};button("Add"){if(!running){val next=steps+Step(name.text,seconds.value as Int);encode(next);steps=next.toMutableList()}};button("Remove"){if(!running&&steps.size>1&&list.selectedIndex in steps.indices)steps.removeAt(list.selectedIndex)};button("Start / restart"){encode(steps);started=System.nanoTime();running=true};button("Stop"){running=false;status.text="Stopped"};button("Save"){val c=JFileChooser();if(c.showSaveDialog(f)==JFileChooser.APPROVE_OPTION)c.selectedFile.bufferedWriter().use{encode(steps).store(it,"Interval sequence")}};button("Open"){if(!running){val c=JFileChooser();if(c.showOpenDialog(f)==JFileChooser.APPROVE_OPTION){val p=Properties();c.selectedFile.bufferedReader().use{p.load(it)};steps=decode(p)}}};val timer=Timer(100){if(running){val(i,left)=active(steps,(System.nanoTime()-started)/1000000000);if(i<0){running=false;status.text="Complete";Toolkit.getDefaultToolkit().beep()}else{list.selectedIndex=i;status.text="${steps[i].name} — ${left}s"}}};timer.start();f.addWindowListener(object:java.awt.event.WindowAdapter(){override fun windowClosing(e:java.awt.event.WindowEvent){timer.stop()}});draw();f.setLocationRelativeTo(null);f.isVisible=true}}
